  "context": {
    "job": {
      "title": "Front End Lead Engineer",
      "description": "Lead the design and development of user-friendly web applications using Vue.js 3, collaborate with cross-functional teams, and integrate with REST APIs. Ensure high performance, maintainability, and adherence to UI/UX best practices.",
      "company": "Advanced Micro Devices",
      "location": "Austin, Texas",
      "contract_type": "W2",
      "duration": "12 months with possibility of extension",
      "start_date": "Immediate",
      "schedule": "Monday through Friday from 8:00 AM to 5:00 PM"
    },
    "candidate": {
      "first_name": "John",
      "last_name": "Doe",
      "email": "john.doe@example.com",
      "phone": "555-555-5555"
    },
    "knowledge_base": {
      "pay_range": "$85.31-$127.25 per hour",
      "worksite_address": "7171 Southwest Parkway, Austin, TX, USA, 78728",
      "benefits": "Health insurance, dental, life insurance, Flexible Spending Account, and 401(k)-retirement plan available after 60 days"
    }
  },

  "tasks": [
    {
      "id": "greeting",
      "title": "Initial Greeting",
      "initial_message": "Hi John, I'm calling to discuss a W2 On Site Front End Lead Engineer opportunity in Austin, Texas that I think you might be interested in. I found your résumé posted online—do you have a few minutes to talk about the job now?",
      "task_agent_type": "GREETING"
    },
    {
      "id": "job_description",
      "title": "Job Description",
      "initial_message": "Great, my name is Phoebe and I'm an AI recruiter from Managed Staffing. We have an hourly W2 opportunity with our client Advanced Micro Devices located in Austin, Texas for a Front End Lead Engineer role. In this position, you will lead the design and development of user-friendly web applications using Vue.js 3, collaborate with cross-functional teams, and integrate with REST APIs. You'll also ensure high performance, maintainability, and adherence to UI/UX best practices. Based on your résumé, it looks like you'd be a great fit. The contract is for 12 months, with the possibility of extension. The work schedule is Monday through Friday from 8:00 AM to 5:00 PM. Would you be interested?",
      "task_instructions": "If they ask about the pay or pay rate, say 'great question' and provide the pay range information: $85.31-$127.25 per hour, depending on experience.",
      "task_agent_type": "CONFIRMATION",
      "adhoc_task_ids_on_unsuccessful": ["not_interested_feedback", "closer"]
    },
    {
      "id": "not_interested_feedback",
      "title": "Feedback if Not Interested",
      "initial_message": "Could you share a bit about why this opportunity isn't the right fit for you and what type of role would suit you better? I'll pass this feedback along to my team so we can better match you with future opportunities.",
      "task_instructions": "Only enter this task if the candidate states they are NOT interested in the job. After collecting their feedback, thank them for their time and end the call.",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["what_looking_for"],
      "is_adhoc_task": true
    },
    {
      "id": "pay_rate",
      "title": "Pay Rate Discussion",
      "initial_message": "What is the minimum hourly rate you are expecting?",
      "task_instructions": "Be sure to verbally confirm their answer before moving on. Pay rates should be in dollar amounts. If they mention a rate less than $15 per hour, assume you misheard and ask again. If they state a rate higher than $127.25 per hour, let them know that the maximum pay rate for this job is $85.31-$127.25 per hour and ask if that works for them.",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["minimum_hourly_rate"],
      "validations": [
        {
          "strategy": "CANDIDATE_DATA_POINT_QUERY",
          "query": "minimum_hourly_rate.value <= 127.25",
          "instructions_on_failure": "The salary expectations are above our budget for this role. Please confirm if the maximum rate of $127.25 per hour works for you.",
          "can_end_call": true
        }
      ]
    },
    {
      "id": "email_confirmation",
      "title": "Pay Rate Confirmation Email",
      "initial_message": "Ok, right after this call I will be sending an email with all the details on this job. Note that salary will be finalized after the client interview. Once you receive it, can you please respond confirming your salary expectations and interest in this job. I need written confirmation before I can submit you to our client and this role is time-sensitive so it is important you respond as soon as possible. Also, please attach a copy of your résumé when you reply. Are you able to do that?",
      "task_agent_type": "CONFIRMATION"
    },
    {
      "id": "vue_experience",
      "title": "Vue.js Experience",
      "initial_message": "Great, and can you describe your experience in front-end development, specifically using Vue.js 3 or a similar JavaScript framework?",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["vue_js_experience"]
    },
    {
      "id": "web_technologies",
      "title": "HTML/CSS/JavaScript Knowledge",
      "initial_message": "Thanks, and can you tell me about your experience and proficiency with HTML5, CSS3, and JavaScript (ES6 or newer)?",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["html_css_js_proficiency"]
    },
    {
      "id": "api_integration",
      "title": "REST API Integration",
      "initial_message": "Thanks, and do you have experience integrating with REST APIs using Java or Spring Boot? Please describe your familiarity.",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["rest_api_experience"]
    },
    {
      "id": "algorithms",
      "title": "Data Structures and Algorithms",
      "initial_message": "Got it, and can you share your experience and knowledge with data structures and algorithms?",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["data_structures_knowledge"]
    },
    {
      "id": "education",
      "title": "Educational Background",
      "initial_message": "Do you have any college degrees? If so, could you tell me the field of study, the year, and the school where the degree was earned?",
      "task_instructions": "Reconfirm with the candidate that they have a college degree if you are not sure.",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["college_degree"],
      "validations": [
        {
          "strategy": "CANDIDATE_DATA_POINT_QUERY",
          "query": "college_degree.value.has_degree == true",
          "instructions_on_failure": "Ok, I understand. Just so you know, this opportunity requires a college degree. We'll continue with the call in case I misinterpreted your response.",
          "can_end_call": false
        }
      ]
    },
    {
      "id": "employment_status",
      "title": "Current Employment Status",
      "initial_message": "Ok and are you currently working?",
      "task_instructions": "If they are working, ask if it's a permanent job or temporary contract. If permanent, ask why they want to change. If temporary/contract, ask when it's ending.",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["current_employment_status"]
    },
    {
      "id": "recent_job",
      "title": "Recent Job Experience",
      "initial_message": "What was your most recent job? Can you tell me briefly about your responsibilities there and roughly what dates you worked there?",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["recent_job_details"]
    },
    {
      "id": "resume_reminder",
      "title": "Updated Resume Reminder",
      "initial_message": "Ok, that reminds me, when you reply to my confirmation email, can you include your most up-to-date résumé if it's different from the one you posted online?",
      "task_agent_type": "INFORMATION"
    },
    {
      "id": "start_date",
      "title": "Availability to Start",
      "initial_message": "If you are offered this job, would you be able to start immediately or would you require a certain notice period?",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["availability_to_start"]
    },
    {
      "id": "legal_name",
      "title": "Legal Name",
      "initial_message": "And can you tell me your full legal name?",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["legal_name"]
    },
    {
      "id": "work_authorization",
      "title": "Work Authorization",
      "initial_message": "Could you please tell me if you are legally authorized to work in the United States and what type of authorization you have if not a US citizen?",
      "task_instructions": "H1B visas are not eligible for this position.",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["work_authorization"],
      "validations": [
        {
          "strategy": "CANDIDATE_DATA_POINT_QUERY",
          "query": "work_authorization.value.authorized == true and work_authorization.value.visa_type != 'H1B'",
          "instructions_on_failure": "This role requires legal authorization to work in the United States and H1B visas are not eligible. Unfortunately we will not be able to move forward.",
          "can_end_call": true
        }
      ]
    },
    {
      "id": "location",
      "title": "Location Information",
      "initial_message": "What is your current zip code, and about how far are you from Austin, Texas?",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["location_details"]
    },
    {
      "id": "transportation",
      "title": "Transportation",
      "initial_message": "Once you receive an offer, do you have your own transportation and a valid driver's license to commute to the worksite at 7171 Southwest Parkway, Austin, TX, USA, 78728?",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["transportation"]
    },
    {
      "id": "contact_number",
      "title": "Contact Information",
      "initial_message": "And do you have an alternate contact number or is this number the best way to get in contact with you?",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["contact_information"]
    },
    {
      "id": "background_check",
      "title": "Background Check Consent",
      "initial_message": "If you are offered the job, we will have to conduct a background check and a drug test, is that OK with you?",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["background_check_consent"],
      "validations": [
        {
          "strategy": "CANDIDATE_DATA_POINT_QUERY",
          "query": "background_check_consent.value == true",
          "instructions_on_failure": "This role requires a background check and a drug test. If you refuse we will be unable to proceed with our client. Do you want to decline or move forward?",
          "can_end_call": true
        }
      ]
    },
    {
      "id": "criminal_history",
      "title": "Criminal History",
      "initial_message": "As we will be performing a drug test and background verification, can you let me know if you have ever been convicted of a felony or misdemeanor?",
      "task_instructions": "If they have convictions, ask for details and whether it's closed/expunged. DO NOT comment on their conviction.",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["criminal_history"]
    },
    {
      "id": "date_of_birth",
      "title": "Date of Birth",
      "initial_message": "I need to collect your date of birth for the background check, but I only need the month and the day, NOT the year. What is your birth month and day?",
      "task_instructions": "Get verbal confirmation that you accurately understood the month and day before moving on.",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["date_of_birth"]
    },
    {
      "id": "interview_availability",
      "title": "Interview Availability",
      "initial_message": "What are the best days and times for our client to conduct an interview during the week?",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["interview_availability"]
    },
    {
      "id": "benefits_overview",
      "title": "Benefits Information",
      "initial_message": "Once you're officially hired, you'll have the option to purchase benefits. These include health insurance, dental, life insurance, a Flexible Spending Account, and a 401(k)-retirement plan. We'll give you all the information about the plans and costs after you're hired. You'll have 30 days to review your options and decide what you'd like to purchase. Just so you know, any benefits you choose will start 60 days after your hire date. Does that work for you?",
      "task_agent_type": "DATA_COLLECTION",
      "candidate_data_points_to_collect": ["benefits_agreement"]
    },
    {
      "id": "conclusion",
      "title": "Call Conclusion",
      "initial_message": "Great, once you do, please expect a call from our recruiter at Managed Staffing who will reach out to finalize details and next steps for the 12-month contract role at Advanced Micro Devices. Thank you and have a wonderful day.",
      "task_agent_type": "INFORMATION"
    },
    {
      "id": "closer",
      "title": "Call Closer",
      "task_agent_type": "CLOSER",
      "task_instructions": "End the call professionally. If the candidate qualified and is moving forward, be positive about next steps. If they didn't qualify or declined, thank them for their time and wish them well."
    }
  ]
}

